#include <iostream>
using namespace std;                                   // std namespace use karo

class Student {                                        // class define karo
    string name;                                       // string variable
    int age;
    double marks;
public:                                                // public members — bahar se accessible
    Student(string n, int a, double m) : name(n), age(a), marks(m) {} // string variable
    void display() {                                   // function define karo
        cout << "Name: " << name << ", Age: " << age << ", Marks: " << marks << endl; // output print karo
    }
    double getMarks() { return marks; }                // value return karo
};

int main() {                                           // main function — yahan se shuru hota hai
    Student s1("Alice", 21, 92.5);
    Student s2("Bob",   22, 85.0);
    s1.display();
    s2.display();
    return 0;                                          // value return karo
}

#include <iostream>
using namespace std;                                   // std namespace use karo

class Animal {                                         // class define karo
public:                                                // public members — bahar se accessible
    string name;                                       // string variable
    Animal(string n) : name(n) {}                      // string variable
    virtual void speak() { cout << name << " makes a sound." << endl; } // output print karo
};

class Dog : public Animal {                            // class define karo
public:                                                // public members — bahar se accessible
    Dog(string n) : Animal(n) {}                       // string variable
    void speak() override { cout << name << " says: Woof!" << endl; } // output print karo
};

class Cat : public Animal {                            // class define karo
public:                                                // public members — bahar se accessible
    Cat(string n) : Animal(n) {}                       // string variable
    void speak() override { cout << name << " says: Meow!" << endl; } // output print karo
};

int main() {                                           // main function — yahan se shuru hota hai
    Animal* a1 = new Dog("Rex");                       // memory allocate karo (C++)
    Animal* a2 = new Cat("Whiskers");                  // memory allocate karo (C++)
    a1->speak(); // Rex says: Woof!
    a2->speak(); // Whiskers says: Meow!
    delete a1; delete a2;                              // memory free karo (C++)
    return 0;                                          // value return karo
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;                                   // std namespace use karo

int main() {                                           // main function — yahan se shuru hota hai
    vector<int> v = {5, 2, 8, 1, 9, 3};                // dynamic array (STL)
    v.push_back(7);                                    // vector mein add karo
    v.push_back(4);                                    // vector mein add karo

    sort(v.begin(), v.end());
    cout << "Sorted: ";                                // output print karo
    for (int x : v) cout << x << " ";                  // output print karo

    cout << "\nSize: " << v.size();                    // output print karo
    cout << "\nMax: " << *max_element(v.begin(), v.end()); // output print karo
    cout << "\nMin: " << *min_element(v.begin(), v.end()) << endl; // output print karo

    v.erase(v.begin());
    v.pop_back();
    cout << "After erase+pop: ";                       // output print karo
    for (int x : v) cout << x << " ";                  // output print karo
    return 0;                                          // value return karo
}

