#include <iostream>
using namespace std;                                   // std namespace use karo

void swapPtr(int* a, int* b) { int t = *a; *a = *b; *b = t; } // integer variable
void swapRef(int& a, int& b) { int t = a; a = b; b = t; } // integer variable

int main() {                                           // main function — yahan se shuru hota hai
    int x = 10, y = 20;                                // integer variable
    cout << "Before swap: x=" << x << " y=" << y << endl; // output print karo
    swapPtr(&x, &y);
    cout << "After ptr swap: x=" << x << " y=" << y << endl; // output print karo
    swapRef(x, y);
    cout << "After ref swap: x=" << x << " y=" << y << endl; // output print karo

    int* p = &x;
    cout << "Address of x: " << p << ", Value: " << *p << endl; // output print karo
    return 0;                                          // value return karo
}

#include <iostream>
using namespace std;                                   // std namespace use karo

template<typename T>
T maxOf(T a, T b) { return (a > b) ? a : b; }          // value return karo

template<typename T>
void printArray(T arr[], int n) {                      // function define karo
    for (int i = 0; i < n; i++) cout << arr[i] << " "; // output print karo
    cout << endl;                                      // output print karo
}

int main() {                                           // main function — yahan se shuru hota hai
    cout << maxOf(10, 20) << endl;         // 20
    cout << maxOf(3.14, 2.71) << endl;    // 3.14
    cout << maxOf('z', 'a') << endl;      // z

    int ints[] = {1, 2, 3, 4, 5};
    double dbls[] = {1.1, 2.2, 3.3};
    printArray(ints, 5);
    printArray(dbls, 3);
    return 0;                                          // value return karo
}

#include <iostream>
using namespace std;                                   // std namespace use karo

long long fib(int n) {
    if (n <= 1) return n;                              // condition check karo
    return fib(n-1) + fib(n-2);                        // value return karo
}

// Memoized version
long long memo[100] = {};
long long fibMemo(int n) {
    if (n <= 1) return n;                              // condition check karo
    if (memo[n]) return memo[n];                       // condition check karo
    return memo[n] = fibMemo(n-1) + fibMemo(n-2);      // value return karo
}

int main() {                                           // main function — yahan se shuru hota hai
    cout << "Fibonacci series (first 10):" << endl;    // output print karo
    for (int i = 0; i < 10; i++) cout << fib(i) << " "; // output print karo
    cout << "\n\nFib(40) memoized: " << fibMemo(40) << endl; // output print karo
    return 0;                                          // value return karo
}

#include <iostream>
#include <stdexcept>
using namespace std;                                   // std namespace use karo

double divide(double a, double b) {
    if (b == 0) throw runtime_error("Division by zero!"); // condition check karo
    return a / b;                                      // value return karo
}

int safeIndex(int arr[], int size, int idx) {          // integer return karne wala function
    if (idx < 0 || idx >= size) throw out_of_range("Index out of bounds!"); // condition check karo
    return arr[idx];                                   // value return karo
}

int main() {                                           // main function — yahan se shuru hota hai
    try {
        cout << divide(10, 2) << endl;   // 5
        cout << divide(10, 0) << endl;   // throws
    } catch (const runtime_error& e) {
        cout << "Error: " << e.what() << endl;         // output print karo
    }

    int arr[] = {1, 2, 3};
    try {
        cout << safeIndex(arr, 3, 10) << endl; // throws
    } catch (const out_of_range& e) {
        cout << "Error: " << e.what() << endl;         // output print karo
    }
    return 0;                                          // value return karo
}

#include <iostream>
#include <vector>
using namespace std;                                   // std namespace use karo

vector<int> sieveOfEratosthenes(int n) {               // dynamic array (STL)
    vector<bool> isPrime(n+1, true);                   // dynamic array (STL)
    isPrime[0] = isPrime[1] = false;
    for (int i = 2; i * i <= n; i++) {                 // integer variable
        if (isPrime[i]) {                              // condition check karo
            for (int j = i*i; j <= n; j += i)          // integer variable
                isPrime[j] = false;
        }
    }
    vector<int> primes;                                // dynamic array (STL)
    for (int i = 2; i <= n; i++)                       // integer variable
        if (isPrime[i]) primes.push_back(i);           // condition check karo
    return primes;                                     // value return karo
}

int main() {                                           // main function — yahan se shuru hota hai
    auto primes = sieveOfEratosthenes(50);
    cout << "Primes up to 50: ";                       // output print karo
    for (int p : primes) cout << p << " ";             // output print karo
    cout << "\nCount: " << primes.size() << endl;      // output print karo
    return 0;                                          // value return karo
}

#include <iostream>
#include <string>
#include <algorithm>
using namespace std;                                   // std namespace use karo

int main() {                                           // main function — yahan se shuru hota hai
    string s = "Hello, QueryNest!";                    // string variable
    cout << "Length: " << s.length() << endl;          // output print karo
    cout << "Upper: "; for (char& c : s) cout << (char)toupper(c); cout << endl; // output print karo
    cout << "Substr: " << s.substr(7, 9) << endl;  // QueryNest
    cout << "Find 'Query': " << s.find("Query") << endl; // 7

    // Replace
    string t = s;                                      // string variable
    size_t pos = t.find("QueryNest");
    if (pos != string::npos) t.replace(pos, 9, "World"); // condition check karo
    cout << "After replace: " << t << endl;            // output print karo

    // Reverse
    string rev = s;                                    // string variable
    reverse(rev.begin(), rev.end());
    cout << "Reversed: " << rev << endl;               // output print karo
    return 0;                                          // value return karo
}

#include <iostream>
#include <vector>
using namespace std;                                   // std namespace use karo

void bubbleSort(vector<int>& arr) {                    // function define karo
    int n = arr.size();                                // integer variable
    for (int i = 0; i < n-1; i++) {                    // integer variable
        bool swapped = false;                          // boolean variable
        for (int j = 0; j < n-i-1; j++) {              // integer variable
            if (arr[j] > arr[j+1]) {                   // condition check karo
                swap(arr[j], arr[j+1]);
                swapped = true;
            }
        }
        if (!swapped) break;                           // condition check karo
    }
}

int main() {                                           // main function — yahan se shuru hota hai
    vector<int> arr = {64, 34, 25, 12, 22, 11, 90};    // dynamic array (STL)
    bubbleSort(arr);
    cout << "Sorted: ";                                // output print karo
    for (int x : arr) cout << x << " ";                // output print karo
    return 0;                                          // value return karo
}

#include <iostream>
#include <vector>
using namespace std;                                   // std namespace use karo

int binarySearch(vector<int>& arr, int target) {       // integer return karne wala function
    int lo = 0, hi = arr.size() - 1;                   // integer variable
    while (lo <= hi) {                                 // jab tak condition True ho
        int mid = lo + (hi - lo) / 2;                  // integer variable
        if (arr[mid] == target) return mid;            // condition check karo
        if (arr[mid] < target) lo = mid + 1;           // condition check karo
        else hi = mid - 1;                             // jab condition False ho
    }
    return -1;                                         // value return karo
}

int main() {                                           // main function — yahan se shuru hota hai
    vector<int> arr = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91}; // dynamic array (STL)
    int targets[] = {23, 100, 2, 91};
    for (int t : targets) {                            // loop — repeat karo
        int idx = binarySearch(arr, t);                // integer variable
        if (idx != -1) cout << t << " found at index " << idx << endl; // output print karo
        else cout << t << " not found" << endl;        // output print karo
    }
    return 0;                                          // value return karo
}

#include <iostream>
using namespace std;                                   // std namespace use karo

int main() {                                           // main function — yahan se shuru hota hai
    int n = 5, num = 1;                                // integer variable
    cout << "Floyd's Triangle:" << endl;               // output print karo
    for (int i = 1; i <= n; i++) {                     // integer variable
        for (int j = 1; j <= i; j++)                   // integer variable
            cout << num++ << "\t";                     // output print karo
        cout << endl;                                  // output print karo
    }
    // Pascal's Triangle
    cout << "\nPascal's Triangle:" << endl;            // output print karo
    for (int i = 0; i < n; i++) {                      // integer variable
        int val = 1;                                   // integer variable
        for (int j = 0; j <= i; j++) {                 // integer variable
            cout << val << " ";                        // output print karo
            val = val * (i - j) / (j + 1);
        }
        cout << endl;                                  // output print karo
    }
    return 0;                                          // value return karo
}

